PENSION_LOWER = 80_000
PENSION_UPPER = 700_000
ALLOWANCE = 110_000
TAPER_FROM = 1_000_000
TAX_BANDS = [(0, 10), (200_000, 24), (600_000, 41)]
SOCIAL_CEILING = 500_000


