                employer_cost(100_000, age)


class YearToDate(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(year_to_date([]), {k: 0 for k in ("gross", "pension", "allowance", "taxable", "tax", "social", "net")})

    def test_sums(self):
        months = [400_000] * 11 + [1_200_000]
